let journalTab='story';
const motion={keys:new Set(),route:[],arrival:null,raf:null,last:null,facing:'south',distance:0,savedAt:0,near:false};
let active='knight',state,view='world',selected='inn',region='all',zoom=1,modal=null,shopMode='buy',shopSelected=null,inventorySelected=null,busy=false,travelTimer=null,toastTimer=null,gpsWatch=null,lastFix=null,gpsMessage='',soundContext=null;
