const spr=(n,cls='')=>{const sheet=n>=24?GEAR_ATLAS:{frames:ATLAS,width:1536,height:1024,file:'./assets/atlas.png'},[x,y,w,h]=sheet.frames[n>=24?n-24:n],m=Math.max(w,h);return `<span class="sprite ${cls}" style="--sprite-sheet:url('${sheet.file}');--aw:${w/m*88}%;--ah:${h/m*88}%;--bw:${sheet.width/w*100}%;--bh:${sheet.height/h*100}%;--sx:${x/(sheet.width-w)*100}%;--sy:${y/(sheet.height-h)*100}%" aria-hidden="true"></span>`;};
