function save(){try{localStorage.setItem(KEY+'.'+active,JSON.stringify(state));localStorage.setItem(ACTIVE,active);if($('#save-status'))$('#save-status').textContent='Postęp zapisany';}catch{if($('#save-status'))$('#save-status').textContent='Zapis niedostępny';toast('Nie udało się zapisać postępu. Wyeksportuj postać w ustawieniach.',true)}}
function sound(type='tap'){if(!state.sound)return;try{soundContext ||= new (window.AudioContext||window.webkitAudioContext)();soundContext.resume();const o=soundContext.createOscillator(),g=soundContext.createGain();o.connect(g);g.connect(soundContext.destination);o.type='triangle';const f={tap:440,hit:180,win:660,coin:880,error:130}[type]||440;o.frequency.setValueAtTime(f,soundContext.currentTime);o.frequency.exponentialRampToValueAtTime(f*(type==='hit'?.45:1.5),soundContext.currentTime+.09);g.gain.setValueAtTime(.045,soundContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,soundContext.currentTime+.16);o.start();o.stop(soundContext.currentTime+.17)}catch{}}
function meter(value,max,kind,label){return `<div><div class="meter-label"><span>${label}</span><span>${Math.floor(value)} / ${max}</span></div><div class="meter ${kind}"><i style="width:${Math.max(0,Math.min(100,value/max*100))}%"></i></div></div>`}
function hud(){const a=E.stats(state),c=CLASSES[state.classId];return `<button class="hero-face" data-action="classes" title="Wybierz klasę bohatera" aria-label="Wybierz klasę bohatera">${spr(c.sprite)}</button><div class="hero-ident"><b>${esc(state.name)}</b><small>${c.name} · poziom <span class="gold">${state.level}</span></small></div><div class="hero-bars">${meter(state.hp,a.maxHp,'hp','ŻYCIE')}${meter(state.mana,a.maxMana,'mana','MANA')}<div class="xp-block"><div class="meter-label"><span>${state.level>=20?'MAKSYMALNY POZIOM':`DO POZIOMU ${state.level+1}: ${E.xpNeed(state.level)-state.xp} PD`}</span><span>${state.level>=20?'MAX':`${state.xp} / ${E.xpNeed(state.level)} PD`}</span></div><div class="meter xp"><i style="width:${state.level>=20?100:state.xp/E.xpNeed(state.level)*100}%"></i></div></div></div>${button(state.skillPoints?`Rozwój · ${state.skillPoints} pkt`:'Karta bohatera','nav:hero','ghost')}`;}
function navButtons(){return [['world','Świat'],['hero','Bohater'],['quest','Zadania'],['town','Miasto']].map(([id,name])=>`<button class="rail-button ${view===id?'active':''}" data-action="nav:${id}" title="${name}">${icon(id)}<span>${name}</span></button>`).join('')}
function render(){state.position=N.safePosition(state.position);const c=CLASSES[state.classId];$('#app').innerHTML=`<div class="app-shell"><aside class="rail"><div class="crest" aria-label="Time4Heroes">4</div><nav class="rail-nav" aria-label="Nawigacja gry">${navButtons()}</nav><div class="rail-bottom"><button class="rail-button" data-action="help">${icon(helpIcon())}<span>Pomoc</span></button><button class="rail-button" data-action="settings">${icon('settings')}<span>Opcje</span></button></div></aside><div class="main-shell"><header class="topbar"><div class="brand"><div class="wordmark">TIME<span>4</span>HEROES</div><small>PIKSELOWE POGRANICZE</small></div><div class="top-actions"><div class="resource" title="Złoto"><span class="coin"></span><b id="gold">${state.gold}</b></div><div class="resource" title="Odłamki przysięgi">${spr(22,'small')}<b id="crystals">${E.count(state,'crystal')}</b></div><div class="top-status"><span class="label-dot"></span><span id="save-status">Postęp zapisany</span></div><button class="icon-button" data-action="settings" aria-label="Ustawienia">${icon('settings')}</button></div></header><section class="hero-strip" aria-label="Stan bohatera">${hud()}</section><div class="content-grid"><main class="main-content" id="main-content">${view==='world'?worldHTML():view==='hero'?heroHTML():view==='quest'?questsHTML():townHTML()}</main><aside class="side-panel" id="side-panel">${sidebarHTML()}</aside></div><footer class="app-footer"><span>TIME4HEROES · 4.2.0 ALPHA · W DRODZE</span><span>JEDNOOSOBOWA PRZYGODA · ZAPIS NA TYM URZĄDZENIU</span></footer></div></div><nav class="mobile-nav" aria-label="Nawigacja mobilna">${navButtons()}</nav>`;if(view==='world')setupMap();setupDrag();}
