function sidebarHTML(){const q=QUESTS[state.quest],progress=E.questProgress(state);return `<section><div class="side-heading"><h2>DZIENNIK WYPRAWY</h2>${iconSmall('quest')}</div>${q?`<div class="chapter-label">ROZDZIAŁ I · ${state.quest+1} / 3</div><h3 class="quest-heading">${q.title}</h3><p class="quest-desc">${q.text}</p><div class="quest-objectives">${progress.map(p=>`<div class="objective ${p.value>=p.need?'done':''}"><i class="checkbox"></i><span>${p.label}</span><b>${Math.min(p.need,p.value)}/${p.need}</b></div>`).join('')}</div>${E.questReady(state)?button('Odbierz nagrodę','questClaim','full'):button('Otwórz dziennik','nav:quest','ghost full')}<div class="quest-rewards"><span>+${q.xp} PD</span><span>+${q.gold} złota</span>${state.quest>0?'<span>+ broń</span>':''}</div>`:`<div class="chapter-label">ROZDZIAŁ I · UKOŃCZONY</div><h3 class="quest-heading">Nowa straż pogranicza</h3><p class="quest-desc">Odzyskano relikt. Możesz ulepszać broń, polować na rzadki pancerz i podejmować kontrakty Straży.</p>${button('Kontrakty Straży','service:guild','ghost full')}`}</section><div class="pixel-rule"></div><div class="side-prompt">${tip()}</div>${huntSidebar()}<section class="journey-card"><div class="side-heading"><h3>Przygoda w terenie</h3>${iconSmall('compass')}</div><p>Graj z domu lub zbieraj dodatkowe zapasy podczas spaceru. Każde 250 m: 3 zioła i 12 złota.</p>${button(gpsWatch===null?'Włącz spacer GPS':'Zatrzymaj GPS','gps','secondary')}<div class="gps-status">${esc(gpsMessage||`Odkryto: ${state.visited.length} miejsc · ${Math.floor(state.gps.distance)} m`)}</div></section>`;}
