function worldHTML(){return `<div class="region-heading"><div><div class="eyebrow">KRÓLESTWO · DOLINA EDRA</div><h1>Zielone Pogranicze</h1></div><div class="region-detail"><span><span class="label-dot"></span> Bezpieczna osada</span><span>Poziomy 1–8</span></div></div><div class="region-tabs">${[['all','Cała okolica'],['village','Osada'],['forest','Leśny szlak'],['ruins','Ruiny']].map(([id,name])=>`<button class="region-tab ${region===id?'active':''}" data-action="region:${id}">${name}</button>`).join('')}</div><div class="world-frame" aria-label="Mapa Zielonego Pogranicza"><div class="world-stage">${LOCATIONS.map(l=>`<button class="place ${l.type==='service'?'service':l.type} ${ENEMIES[l.id]?.boss?'boss':''} ${selected===l.id?'selected':''}" style="left:${l.x}%;top:${l.y}%" data-action="location:${l.id}" aria-label="${l.name}, ${l.tag}">${l.type==='service'?`<span class="marker">${icon({inn:'home',smith:'sword',alchemist:'leaf',guild:'shield'}[l.service])}</span>`:spr(l.sprite)}${l.type==='enemy'?`<span class="level-tag">${ENEMIES[l.id].boss?'BOSS ':''}${ENEMIES[l.id].level}</span>`:''}${l.type==='gather'||l.type==='chest'?'<span class="marker">+</span>':''}<span class="place-label">${l.name}</span></button>`).join('')}<div class="player-marker" style="left:${state.position.x}%;top:${state.position.y}%">${walkSprite()}</div>${[1,2,3,4,5,6].map((n)=>`<i class="sprinkle" style="left:${62+n*3}%;top:${30+n*8}%;animation-delay:${n*1.4}s"></i>`).join('')}</div><div class="map-grain"></div><div class="map-top"><span class="label-dot"></span> BRAMA OTWARTA · DZIEŃ</div><div class="map-caption">Strzałki / WASD · kliknij ścieżkę lub cel</div><div class="walk-pad" aria-label="Sterowanie ruchem"><button class="walk-control north" data-direction="north" aria-label="Idź w górę">↑</button><button class="walk-control west" data-direction="west" aria-label="Idź w lewo">←</button><button class="walk-control south" data-direction="south" aria-label="Idź w dół">↓</button><button class="walk-control east" data-direction="east" aria-label="Idź w prawo">→</button></div><div class="map-controls"><button data-action="zoom:-" aria-label="Oddal mapę">−</button><button data-action="zoom:reset" aria-label="Wyśrodkuj mapę">⌖</button><button data-action="zoom:+" aria-label="Przybliż mapę">+</button></div></div><div class="world-legend"><span><i class="legend-mark"></i>Usługi</span><span><i class="legend-mark enemy"></i>Przeciwnicy</span><span><i class="legend-mark boss"></i>Boss</span><button class="inline-link" data-action="journal:bestiary">Bestiariusz</button><span class="legend-end">${state.visited.length} / ${LOCATIONS.length} odkrytych miejsc</span></div><div id="location-card">${locationHTML()}</div>`;}
function locationHTML(){const l=LOCATIONS.find(l=>l.id===selected)||LOCATIONS[0],near=N.nearLocation(state.position,l.id),e=ENEMIES[l.id],locked=e?E.eliteRequirement(state,l.id):null;return `<section class="location-card">${spr(l.sprite)}<div><span class="eyebrow">${l.tag}</span><h3>${l.name}</h3><p>${e?e.desc:l.type==='gather'?'Zbierz zioła i uwarz z nich tańsze mikstury.':l.type==='chest'?(state.chest?'Znalezione zapasy już trafiły do plecaka.':'Zaginiony patrol zostawił tutaj zapasy i znak dawnej straży.'):{inn:'Nessa zna każdy szlak. Odpocznij i przygotuj się do kolejnej wyprawy.',smith:'Porównaj broń, kup pancerz i wykorzystaj zdobyte kły.',alchemist:'Mikstury życia i many. Własne zioła obniżają koszt leczenia.',guild:'Za zwycięstwa i dostarczone materiały odbierzesz nowe nagrody.'}[l.service]}</p>${e?`<p class="location-drops">Łupy: ${e.loot.map(([id])=>ITEMS[id].name).join(' · ')}</p>`:''}</div><div class="location-actions">${button(travelTimer?'W drodze…':!near?'Podejdź ścieżką':e?'Rozpocznij walkę':l.type==='gather'?'Zbierz zioła':l.type==='chest'?'Sprawdź skrzynię':'Wejdź do środka','interact:'+l.id,'',!!travelTimer)}${e?button('Elita · poz. '+(e.level+3),'elite:'+l.id,'elite-button',!!locked||!!travelTimer):''}${e&&locked?`<small>${locked}</small>`:''}</div></section>`;}
function walkSprite(){return '<span class="walk-sprite" aria-hidden="true"><span class="walk-body"></span></span>';}
function paintWalker(walking=false){
 const marker=$('.player-marker'),body=$('.walk-body');if(!marker||!body)return;
 marker.style.left=state.position.x+'%';marker.style.top=state.position.y+'%';
 const art=WALK_ATLAS[state.classId],row=state.classId==='ranger'&&motion.facing==='west'?2:['south','west','east','north'].indexOf(motion.facing),frame=walking&&!matchMedia('(prefers-reduced-motion:reduce)').matches?Math.floor(motion.distance/16)%4:1;
 const [x,y,w,h,anchor]=art.frames[row*4+frame],scale=52/art.maxHeight;
 Object.assign(body.style,{backgroundImage:`url('${art.file}')`,backgroundSize:`${art.width*scale}px ${art.height*scale}px`,backgroundPosition:`${-x*scale}px ${-y*scale}px`,width:w*scale+'px',height:h*scale+'px',left:(x-anchor)*scale+'px',transform:state.classId==='ranger'&&motion.facing==='west'?'scaleX(-1)':'none',transformOrigin:`${(anchor-x)*scale}px bottom`});
 marker.classList.toggle('walking',walking);
}
function stopMovement(persist=true){
 if(motion.raf!==null)cancelAnimationFrame(motion.raf);
 motion.raf=null;motion.last=null;motion.route=[];motion.keys.clear();motion.arrival=null;travelTimer=null;
 if(view==='world'){paintWalker(false);updateLocationCard();}if(persist&&state)save();
}
function movementAllowed(){return view==='world'&&!modal&&!state.combat&&!state.pending&&!document.hidden;}
function wakeMovement(){if(motion.raf===null){motion.last=null;motion.raf=requestAnimationFrame(tickMovement);}}
function tickMovement(time){
 motion.raf=null;if(!movementAllowed()){stopMovement();return;}
 const seconds=motion.last===null?0:Math.min(.05,Math.max(0,(time-motion.last)/1000));motion.last=time;
 const before=N.fromPercent(state.position),vector=N.inputVector(motion.keys);let after=before;
 if(vector.x||vector.y){motion.route=[];motion.arrival=null;travelTimer=null;after=N.moveOnRoad(before,vector.x*N.SPEED*seconds,vector.y*N.SPEED*seconds);}
 else if(motion.route.length)after=N.advanceRoute(before,motion.route,N.SPEED*seconds).position;
 const moved=Math.hypot(after.x-before.x,after.y-before.y);state.position=N.toPercent(after);
 if(moved>.0001){motion.facing=N.facing(after.x-before.x,after.y-before.y,motion.facing);motion.distance+=moved;paintWalker(true);followWalker();}
 else paintWalker(false);
 if(time-motion.savedAt>1500&&moved){save();motion.savedAt=time;}
 const near=LOCATIONS.find(l=>N.nearLocation(state.position,l.id));
 if(near&&selected!==near.id&&!travelTimer){selected=near.id;markArrival(near.id);}
 const available=N.nearLocation(state.position,selected)&&!motion.route.length;
 if(available!==motion.near){motion.near=available;updateLocationCard();}
 if(motion.keys.size||motion.route.length){motion.raf=requestAnimationFrame(tickMovement);return;}
 const arrive=motion.arrival;motion.arrival=null;travelTimer=null;motion.last=null;paintWalker(false);save();updateLocationCard();
 if(arrive){markArrival(arrive.id);if(arrive.interact)performLocation(arrive.id,arrive.elite);}
}
function updateLocationCard(){const card=$('#location-card');if(view==='world'&&card)card.innerHTML=locationHTML();}
function markArrival(id){if(!state.visited.includes(id)){state.visited.push(id);refresh();}$$('.place').forEach(b=>b.classList.toggle('selected',b.dataset.action==='location:'+id));updateLocationCard();}
function routePoint(target,arrival=null){
 if(!movementAllowed())return false;
 if(!N.isWalkable(target))return false;
 stopMovement(false);motion.route=N.routeTo(N.fromPercent(state.position),target);motion.arrival=arrival;
 if(!motion.route.length){if(arrival){markArrival(arrival.id);if(arrival.interact)performLocation(arrival.id,arrival.elite);}return true;}
 travelTimer=true;updateLocationCard();wakeMovement();return true;
}
function travel(id,interact=false,elite=false){
 if(state.combat||state.pending)return showEncounter();if(!N.ACCESS[id])return;
 selected=id;routePoint(N.ACCESS[id],{id,interact,elite});updateLocationCard();
}
function performLocation(id,elite=false){
 if(state.combat||state.pending)return showEncounter();
 if(!N.nearLocation(state.position,id))return travel(id,true,elite);
 const l=LOCATIONS.find(l=>l.id===id);if(!l)return;stopMovement();markArrival(id);
 if(l.type==='enemy'){const error=E.startFight(state,id,elite);if(error)return toast(error,true);save();showEncounter();}
 else if(l.type==='service')openService(l.service);
 else if(l.type==='gather')transact(E.gather(state),'Zebrano 2 wiązki srebrzystego ziela.',false);
 else if(l.type==='chest'){transact(E.openChest(state),'Skrzynia: 30 złota, 2 mikstury i 2 kły.',false);updateLocationCard();}
}
function followWalker(){
 const frame=$('.world-frame'),stage=$('.world-stage');if(!frame||!stage)return;
 if(matchMedia('(max-width:600px)').matches){const w=660*zoom,h=440*zoom,fh=frame.clientHeight;stage.style.left=Math.min(0,Math.max(frame.clientWidth-w,frame.clientWidth/2-w*state.position.x/100))+'px';stage.style.top=Math.min(0,Math.max(fh-h,fh/2-h*state.position.y/100))+'px';}
 else if(zoom>1)stage.style.transformOrigin=`${state.position.x}% ${state.position.y}%`;
}
function setupMap(){
 const frame=$('.world-frame'),stage=$('.world-stage');if(!frame||!stage)return;
 const mobile=matchMedia('(max-width:600px)').matches,focus={all:.5,village:.25,forest:.71,ruins:.86}[region];
 if(mobile){const w=660*zoom,h=440*zoom;stage.style.width=w+'px';stage.style.height=h+'px';stage.style.left=Math.min(0,Math.max(frame.clientWidth-w,frame.clientWidth/2-w*focus))+'px';stage.style.top='0';stage.style.transform='none';}
 else{stage.style.width='100%';stage.style.height='100%';stage.style.left='0';stage.style.top='0';stage.style.transform=`scale(${zoom})`;stage.style.transformOrigin=`${focus*100}% 50%`;}
 paintWalker(!!motion.route.length);let drag=null;
 frame.onpointerdown=e=>{if(e.target.closest('button')||!movementAllowed())return;drag={x:e.clientX,y:e.clientY,left:parseFloat(stage.style.left)||0,moved:false};};
 frame.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>8)drag.moved=true;if(mobile&&Math.abs(dx)>Math.abs(dy)){stage.style.left=Math.max(frame.clientWidth-660*zoom,Math.min(0,drag.left+dx))+'px';}};
 frame.onpointerup=e=>{if(!drag)return;const wasDrag=drag.moved;drag=null;if(wasDrag||e.target.closest('button'))return;const rect=stage.getBoundingClientRect(),target={x:(e.clientX-rect.left)/rect.width*N.WORLD.width,y:(e.clientY-rect.top)/rect.height*N.WORLD.height};if(!routePoint(target))toast('Wybierz ścieżkę. Las, zabudowania i rzeka blokują przejście.');};
 frame.onpointercancel=()=>drag=null;
 $$('.walk-control').forEach(b=>{b.onpointerdown=e=>{if(!movementAllowed())return;e.preventDefault();b.setPointerCapture?.(e.pointerId);motion.keys.add(b.dataset.direction);motion.route=[];motion.arrival=null;travelTimer=null;updateLocationCard();wakeMovement();};const release=()=>{motion.keys.delete(b.dataset.direction);};b.onpointerup=release;b.onpointercancel=release;b.onlostpointercapture=release;});
}
function heroHTML(){const a=E.stats(state),c=CLASSES[state.classId];return `<div class="view-heading"><div class="eyebrow">TWOJA OPOWIEŚĆ</div><h1>Bohater i wyposażenie</h1><p>Lepsza broń. Wyraźnie mocniejszy cios.</p></div><div class="paper-layout"><div class="paperdoll"><span class="eyebrow">${c.tag}</span>${spr(c.sprite)}<h2>${esc(state.name)}</h2><small>${c.name} · poziom ${state.level}</small><div class="gear-slots">${[['weapon','Broń'],['armor','Pancerz'],['offhand','Tarcza']].map(([slot,label])=>{const i=state.inventory.find(i=>i.uid===state.equipped[slot]);return `<button class="gear-slot" data-slot="${slot}" data-action="gear:${slot}" aria-label="${label}${i?': '+ITEMS[i.id].name:''}">${i?spr(ITEMS[i.id].sprite):icon(slot==='weapon'?'sword':'shield')}<small>${label}</small></button>`}).join('')}</div></div><div><div class="stats-grid">${[['Atak',a.attack],['Pancerz',a.armor],['Krytyk',Math.round(a.crit*100)+'%'],['Życie',a.maxHp],['Mana',a.maxMana],['Punkty zdolności',state.skillPoints]].map(([label,value])=>`<div class="stat-tile"><small>${label}</small><b>${value}</b></div>`).join('')}</div><div class="inventory-title"><h2>Plecak</h2><small>${state.inventory.length} / 36 miejsc</small></div><div class="inventory-grid">${Array.from({length:E.CAPACITY},(_,n)=>{const i=state.inventory[n],d=E.itemInfo(i);return `<button class="inventory-cell ${d?.rarity||''} ${inventorySelected===i?.uid?'selected':''}" ${i?`data-uid="${i.uid}" draggable="${!!d.slot}" data-action="item:${i.uid}" aria-label="${d.name}, ${i.qty} sztuk"`:'disabled aria-label="Puste miejsce"'}>${i?spr(d.sprite)+(i.qty>1?`<span class="qty">${i.qty}</span>`:'')+(Object.values(state.equipped).includes(i.uid)?'<span class="equipped-mark">◆</span>':'')+(i.upgrade?`<span class="qty">+${i.upgrade}</span>`:''):''}</button>`}).join('')}</div><p class="inventory-hint">Kliknij przedmiot, aby zobaczyć szczegóły. Broń i pancerz możesz przeciągnąć do pola wyposażenia.</p><div id="item-inspector">${inventorySelected?inventoryDetails(inventorySelected):'<div class="empty-note">Wybierz przedmiot z plecaka.</div>'}</div></div></div><section class="skill-section"><div class="inventory-title"><h2>Umiejętności klasy</h2><span class="badge gold">${state.skillPoints} pkt do wydania</span></div><div class="skill-grid">${c.skills.map(([id,name,cost,mult,effect])=>`<article class="skill-card"><h3>${name}</h3><p>${state.skills[id]?`Poziom ${state.skills[id]}/3`:'Do nauczenia'} · ${cost} many<br>${effect==='heal'?'Leczenie '+Math.round((.26+.05*((state.skills[id]||1)-1))*100)+'% życia':effect==='guard'?'Redukcja ciosu o '+Math.round((.78+.04*((state.skills[id]||1)-1))*100)+'%':Math.round(mult*(1+.12*((state.skills[id]||1)-1))*100)+'% obrażeń'+(effect==='stun'?' · przerwanie':['poison','burn','bleed'].includes(effect)?' · obrażenia w czasie':'')}</p>${button(state.skills[id]?'Rozwiń':'Naucz się','learn:'+id,'secondary',!state.skillPoints||(state.skills[id]||0)>=3)}</article>`).join('')}</div></section>`;}
function inventoryDetails(uid){const i=state.inventory.find(i=>i.uid===uid);if(!i)return '';const d=E.itemInfo(i),equipped=Object.values(state.equipped).includes(uid);return `<article class="item-inspector ${d.rarity}">${spr(d.sprite)}<div><small>${RARITY[d.rarity]}${d.level?' · poziom '+d.level:''}</small><h3 class="item-name">${d.name}${i.upgrade?' +'+i.upgrade:''}</h3><p>${d.desc}</p><div class="item-statline">${itemStats(d,i)}</div>${d.slot?comparisonHTML(d,i):''}<div class="item-actions">${d.slot?button(equipped?'Założony':'Załóż','equip:'+uid,'',equipped):d.type==='consumable'?button('Użyj','use:'+uid):''}${button('Sprzedaj · '+(d.sell||0)+' zł','sellOne:'+uid,'ghost',equipped)}</div></div></article>`;}
function itemStats(d,i={}){const info=i.id?E.itemInfo(i):d;return [info.attack?`Atak +${info.attack}`:'',info.armor?`Pancerz +${info.armor}`:'',info.hp?`Życie +${info.hp}`:'',info.maxMana?`Maks. mana +${info.maxMana}`:'',info.crit?`Krytyk +${Math.round(info.crit*100)} p.p.`:'',info.heal?`Leczenie ${info.heal}`:'',info.mana?`Mana +${info.mana}`:''].filter(Boolean).map(x=>`<span>${x}</span>`).join('')}
function comparisonHTML(d,inst={}){if(!d.slot)return '';const current=state.inventory.find(i=>i.uid===state.equipped[d.slot]),old=E.itemInfo(current),next=inst.id?E.itemInfo(inst):d,fields=[['attack','Atak'],['armor','Pancerz'],['hp','Życie'],['maxMana','Maks. mana'],['crit','Krytyk']];return `<div class="comparison">Założone: ${old?old.name:'brak'}${current?.upgrade?' +'+current.upgrade:''}<br>${fields.filter(([k])=>next[k]||old?.[k]).map(([k,label])=>{const factor=k==='crit'?100:1,before=Math.round((old?.[k]||0)*factor),after=Math.round((next[k]||0)*factor),delta=after-before;return `${label}: ${before} → ${after}${k==='crit'?'%':''} <b class="${delta>0?'better':delta<0?'worse':''}">(${delta>0?'+':''}${delta}${k==='crit'?' p.p.':''})</b>`}).join(' · ')}</div>`;}
function storyHTML(){const q=QUESTS[state.quest];return `<div class="view-heading"><div class="eyebrow">ROZDZIAŁ I</div><h1>Zaginiony patrol</h1><p>Trzy spotkania, jedna zapomniana przysięga.</p></div>${q?`<article class="quest-page-card"><span class="badge gold">AKTYWNE ZADANIE</span><h2>${q.title}</h2><p>${q.text}</p><div class="quest-objectives">${E.questProgress(state).map(p=>`<div class="objective ${p.value>=p.need?'done':''}"><i class="checkbox"></i><span>${p.label}</span><b>${Math.min(p.need,p.value)}/${p.need}</b></div>`).join('')}</div><div class="quest-rewards">+${q.xp} PD · +${q.gold} złota${state.quest>0?' · broń dla Twojej klasy':''}</div><div class="item-actions">${button(E.questReady(state)?'Odbierz nagrodę':'Wróć na szlak',E.questReady(state)?'questClaim':'nav:world')}</div></article>`:'<article class="quest-page-card"><span class="badge gold">PRZYSIĘGA ODNOWIONA</span><h2>Twoja broń ma już historię.</h2><p>Nessa zawiesiła znak nowej straży nad bramą. Zaopatrz się, ulepsz relikt u Torena i wróć do ruin po rzadki pancerz.</p></article>'}${QUESTS.filter(q=>state.questClaimed.includes(q.id)).reverse().map(q=>`<article class="quest-page-card completed"><span class="eyebrow">UKOŃCZONE</span><h2>${q.title}</h2><p>Nagroda odebrana. Ten fragment opowieści został zapisany.</p></article>`).join('')}`;}
function townHTML(){return `<div class="view-heading"><div class="eyebrow">TWOJE SCHRONIENIE</div><h1>Osada Zielonej Straży</h1><p>Odpocznij, uzupełnij zapasy i przygotuj następny krok.</p></div><div class="town-intro"><div class="town-title"><span class="eyebrow">DOLINA EDRA</span><h2>Dobrze być z powrotem.</h2></div></div><div class="town-grid">${LOCATIONS.filter(l=>l.type==='service').map(l=>`<button class="town-service" data-action="service:${l.service}">${spr(l.sprite)}<div><h3>${l.name}</h3><p>${l.tag}</p></div></button>`).join('')}</div><div class="side-prompt" style="margin-top:20px">${state.rep} reputacji u Straży · wszystkie usługi są dostępne także z domu.</div>`;}
function openModal(title,body,subtitle='POGRANICZE',cls=''){stopMovement();const old=$('.modal')?.scrollTop||0;$('#overlay').hidden=false;$('#overlay').innerHTML=`<section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><div><span class="eyebrow">${subtitle}</span><h2>${title}</h2></div><button class="icon-button" data-action="close" aria-label="Zamknij">${icon('close')}</button></header><div class="modal-body">${body}</div></section>`;$('.modal').scrollTop=old;document.body.style.overflow='hidden';}
function closeModal(){if(state.combat||state.pending)return;$('#overlay').hidden=true;$('#overlay').innerHTML='';document.body.style.overflow='';modal=null;}
function openService(id,keep=false){if(state.combat||state.pending)return showEncounter();modal='service:'+id;if(!keep){shopMode='buy';shopSelected=null;}if(id==='inn'){openModal('Karczma Pod Lisem',`<div class="npc-intro">${spr(5,'large')}<div><span class="eyebrow">NESSA · GOSPODYNI</span><p>„Każda dobra wyprawa zaczyna się od pełnego plecaka i odpoczynku. A każda dobra opowieść — od kogoś, kto wrócił”.</p></div></div><div class="quest-page-card"><h2>${QUESTS[state.quest]?.title||'Straż wróciła do domu'}</h2><p>${QUESTS[state.quest]?.text||'Nessa wita Cię jak jednego z dawnych strażników. Pogranicze znów ma swojego obrońcę.'}</p><div class="item-actions">${button(E.questReady(state)?'Oddaj zadanie':'Zobacz dziennik',E.questReady(state)?'questClaim':'closeQuest','secondary')}</div></div><div class="forge-upgrade">${spr(18)}<div><b>Ciepły posiłek i odpoczynek</b><p>Pełne życie i mana · ${state.gold>=8?'8 złota':'na koszt Nessy'}</p></div>${button('Odpocznij','rest')}</div>`,'BEZPIECZNE MIEJSCE');return;}
 if(id==='guild'){const total=Object.values(state.kills).reduce((a,b)=>a+b,0),progress=Math.max(0,total-state.bounty);openModal('Brama Straży',`<div class="npc-intro">${spr(0,'large')}<div><span class="eyebrow">STRAŻ POGRANICZA</span><p>„Dbaj o szlaki, a zadbamy o Twoje zapasy. Co pięciu pokonanych przeciwników możesz odebrać kolejną nagrodę”.</p></div></div>${button('Zlecenia i polowania','journal:hunts','secondary full')}<div class="quest-page-card"><span class="badge gold">POWTARZALNY KONTRAKT</span><h2>Bezpieczne pogranicze</h2><p>Pokonaj 5 dowolnych przeciwników. Po odebraniu nagrody następny kontrakt jest dostępny od razu. Imienne zlecenia na skóry i elity znajdziesz w zakładce Polowania.</p><div class="quest-rewards">${Math.min(5,progress)} / 5 pokonanych · 22 złota · +5 reputacji</div><div class="item-actions">${button('Odbierz nagrodę','bounty','',progress<5)}</div></div><p class="version-note">Twoja reputacja: ${state.rep}. To kontrakty miejscowej Straży w przygodzie jednoosobowej.</p>`,'LOKALNE KONTRAKTY');return;}
 const ids=id==='alchemist'?['potion','mana','strongPotion']:[CLASSES[state.classId].weapon+'0',CLASSES[state.classId].weapon+'1','leather','scoutArmor',...(state.classId==='knight'?['shield']:[])];
 const selectedItem=shopMode==='buy'?ITEMS[shopSelected]:E.itemInfo(state.inventory.find(i=>i.uid===shopSelected)),chosenInst=shopMode==='sell'?state.inventory.find(i=>i.uid===shopSelected):null;
 openModal(id==='smith'?'Kuźnia Torena':'Pracownia Eldry',`<div class="npc-intro">${spr(id==='smith'?12:19)}<div><span class="eyebrow">${id==='smith'?'TOREN · KOWAL':'ELDRA · ALCHEMICZKA'}</span><p>${id==='smith'?'„Dobry oręż poznasz po tym, jak szybko ucisza las. Przynieś kły — wzmocnię ostrze”.':'„Zioła ze szlaku są równie dobre jak złoto. Z własnych składników uwarzysz tańsze lekarstwo”.'}</p></div></div><div class="shop-tabs"><button class="${shopMode==='buy'?'active':''}" data-action="shopTab:buy">Kupowanie</button><button class="${shopMode==='sell'?'active':''}" data-action="shopTab:sell">Sprzedaż</button><span class="badge gold" style="margin-left:auto">${state.gold} złota</span></div><div class="shop-grid">${(shopMode==='buy'?ids.map(id=>({id,uid:id,qty:1})):state.inventory).map(i=>{const d=E.itemInfo(i);return `<button class="shop-item ${d.rarity} ${shopSelected===i.uid?'selected':''}" data-action="shopSelect:${i.uid}">${spr(d.sprite)}<b class="item-name">${d.name}${i.upgrade?' +'+i.upgrade:''}</b><small>${shopMode==='sell'?`${i.qty} szt. · `:''}${d.level?'Poziom '+d.level:RARITY[d.rarity]}</small><span class="price">${shopMode==='buy'?d.price:d.sell} złota</span></button>`}).join('')||'<div class="empty-note">Plecak jest pusty.</div>'}</div>${selectedItem?`<div class="item-inspector ${selectedItem.rarity}">${spr(selectedItem.sprite)}<div><h3 class="item-name">${selectedItem.name}</h3><p>${selectedItem.desc}</p><div class="item-statline">${itemStats(selectedItem,chosenInst||{})}</div>${shopMode==='buy'?comparisonHTML(selectedItem):''}<div class="shop-buy-bar"><label>Ilość <input id="shopQty" type="number" min="1" max="${shopMode==='sell'?chosenInst.qty:99}" value="1" inputmode="numeric"></label>${button(shopMode==='buy'?'Kup przedmiot':'Sprzedaj przedmiot',shopMode==='buy'?'buySelected':'sellSelected')}</div></div></div>`:'<p class="choice-note">Wybierz przedmiot, aby zobaczyć opis, porównać wyposażenie i ustawić ilość.</p>'}${id==='smith'?forgeHTML()+enchantHTML():`<div class="forge-upgrade">${spr(23)}<div><b>Uwarz miksturę życia</b><p>3 zioła + 6 złota · zioła w plecaku: ${E.count(state,'herb')}</p></div>${button('Uwarz','brew','secondary',E.count(state,'herb')<3||state.gold<6)}</div>`}`,'HANDEL I ZAOPATRZENIE');}
function forgeHTML(){const i=state.inventory.find(i=>i.uid===state.equipped.weapon);if(!i)return '';return `<div class="forge-upgrade">${spr(ITEMS[i.id].sprite)}<div><b>${E.itemInfo(i).name}${i.upgrade?' +'+i.upgrade:''}</b><p>${(i.upgrade||0)>=3?'Maksymalne ulepszenie +3':`Następne ulepszenie: +2 ataku · 2 kły + ${25+25*(i.upgrade||0)} złota`}</p><small>Kły w plecaku: ${E.count(state,'fang')}</small></div>${button('Ulepsz','upgrade','secondary',(i.upgrade||0)>=3)}</div>`;}
function openClasses(){if(state.combat||state.pending)return toast('Najpierw zakończ walkę i odbierz łupy.',true);modal='classes';openModal('Wybierz swoją drogę',`<div class="class-grid">${Object.entries(CLASSES).map(([id,c])=>`<button class="class-card ${id===state.classId?'active':''}" data-action="class:${id}">${spr(c.sprite)}<b>${c.name}</b><small>${c.tag}</small></button>`).join('')}</div><p class="class-description">${CLASSES[state.classId].desc}<br>Każda klasa ma osobny zapis. Możesz wrócić do rozwiniętego bohatera bez utraty jego postępu.</p>`,'PIĘĆ KLAS · JEDEN ŚWIAT');}
function projectDownload(){const loc=globalThis.location;if(loc?.hostname?.endsWith('.github.io')){const owner=loc.hostname.slice(0,-10),first=loc.pathname.split('/').filter(Boolean)[0],repo=first&&!first.endsWith('.html')?first:owner+'.github.io';return `<a href="https://github.com/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}" target="_blank" rel="noopener noreferrer">Kod na GitHubie</a>`;}return '<a href="./downloads/Time4Heroes_PIXEL_4_2.zip" download>Pobierz ZIP</a>';}
function openSettings(){if(state.combat||state.pending)return toast('Ustawienia otworzysz po walce.',true);modal='settings';openModal('Ustawienia przygody',`<div class="setting-row"><div><b>Imię bohatera</b><p>Do 18 znaków.</p></div><input id="heroName" value="${esc(state.name)}" maxlength="18" aria-label="Imię bohatera">${button('Zapisz','rename','secondary')}</div><div class="setting-row"><div><b>Dźwięki</b><p>Krótkie dźwięki walki i zdobywania łupów.</p></div><button class="switch" data-action="sound">${state.sound?'WŁĄCZONE':'WYŁĄCZONE'}</button></div><div class="setting-row"><div><b>Spacer GPS</b><p>Opcjonalny. Nie blokuje miasta ani zwykłych wypraw.</p><p>${esc(gpsMessage||'250 m = 3 zioła i 12 złota.')}</p></div>${button(gpsWatch===null?'Włącz GPS':'Wyłącz GPS','gps','secondary')}</div><div class="setting-row"><div><b>Kopia postaci</b><p>Postęp jest zapisany na tym urządzeniu. Eksportuj go przed zmianą urządzenia.</p></div>${button('Eksportuj','export','secondary')}${button('Importuj','import','ghost')}<input id="importFile" class="settings-file" type="file" accept="application/json"></div><div class="setting-row"><div><b>Projekt gry</b><p>Pełny kod i nowe grafiki tej wersji.</p></div>${projectDownload()}</div><p class="version-note">${VERSION}<br>Nowy początek z osobnym zapisem. Zapis wersji pixel 4.0 działa także tutaj. Zapisów 3.9.9.8 nie importujemy do tej wersji. Pierwszy grywalny rozdział obejmuje pogranicze, pięć klas, zadania i relikt. Multiplayer i rozbudowa miasta nie są częścią tego rozdziału.</p>`,'USTAWIENIA');}
function openHelp(){modal='help';openModal('Pierwsze kroki na pograniczu',`<ol class="help-list"><li><b>Wybierz miejsce na mapie.</b> Kliknięcie prowadzi bohatera po ścieżkach do celu. Na komputerze możesz chodzić strzałkami lub WASD, a na telefonie przyciskami na mapie. Las, budynki i rzeka blokują ruch; rzekę przekroczysz mostem. Przycisk pod mapą rozpoczyna spotkanie po podejściu do celu. Klawisz Escape zatrzymuje marsz.</li><li><b>Zacznij od wilków lub śluzów.</b> Zdobędziesz doświadczenie, złoto i materiały. Odbierz łupy po walce.</li><li><b>Reaguj na zapowiedzi.</b> Obrona zmniejsza następny cios, a zdolność kontrolująca może przerwać atak. Rycerz z tarczą przygotowuje odwet. Zablokowany mocny cios lub przerwanie odsłania przeciwnika: następny atak zada +35% obrażeń.</li><li><b>Załóż lepszą broń.</b> Kliknij ją w plecaku lub przeciągnij do pola. U Torena sprawdzisz różnicę przed zakupem.</li><li><b>Wybierz cel polowania.</b> W Zadaniach znajdziesz Polowania i Bestiariusz. Pokazują wymagane materiały, konkretne nagrody oraz szanse na łupy z elit.</li><li><b>Wydawaj punkty po awansie.</b> Karta bohatera zawiera nowe zdolności i ich rozwój.</li><li><b>Graj w swoim tempie.</b> Karczma odnawia siły. Życie i mana wracają także poza walką, gdy gra jest zamknięta. GPS jest opcjonalny.</li></ol>`,'PRZEWODNIK');}
function showEncounter(){if(state.pending)return showReward();if(!state.combat)return;modal='combat';const c=state.combat,e=E.enemyInfo(c),a=E.stats(state),cls=CLASSES[state.classId];$('#overlay').hidden=false;document.body.style.overflow='hidden';$('#overlay').innerHTML=`<section class="modal battle-modal" role="dialog" aria-modal="true" aria-label="Walka z ${e.name}"><header class="battle-header"><div><span class="eyebrow">${e.elite?'POLOWANIE NA ELITĘ':e.boss?'STRAŻNIK RUIN':'SPOTKANIE NA SZLAKU'}</span><br><strong>${e.region}</strong></div><span class="badge gold">TURA ${c.turn}</span></header><div class="battle-field"><div class="fighter player-fighter"><div class="fighter-name">${esc(state.name)}<small>POZ. ${state.level}</small></div><div class="fighter-bars" id="battle-player-bars">${meter(state.hp,a.maxHp,'hp','ŻYCIE')}${meter(state.mana,a.maxMana,'mana','MANA')}</div><div class="actor-wrap" id="player-actor">${spr(cls.sprite)}</div></div><span class="battle-versus">VS</span><div class="fighter enemy-fighter ${e.elite?'elite-fighter':''} ${e.boss?'boss':''}"><div class="fighter-name">${e.name}<small>POZ. ${e.level}</small></div><div class="fighter-bars" id="battle-enemy-bars">${meter(c.hp,e.hp,'hp','ŻYCIE')}</div><div class="actor-wrap" id="enemy-actor">${spr(e.sprite)}</div></div></div><div class="battle-intent ${c.intent?'danger':''}"><span>${c.intent?`${e.intent}. Broń się lub przerwij atak.`:c.dotTurns?`Cel otrzymuje ${c.dot} obrażeń przez jeszcze ${c.dotTurns} tury.`:'Przeciwnik obserwuje Twój ruch.'}</span><span>${c.exposed?'ODSŁONIĘCIE +35%':c.retaliation?'ODWET +50%':'Atak '+a.attack+' · Pancerz '+a.armor}</span></div><div class="battle-tactics">${c.ailment?`<b class="danger">${c.ailment==='poison'?'Trucizna':'Krwawienie'} · ${c.ailmentTurns} tury. Mikstura życia usuwa efekt.</b>`:c.exposed?'<b class="good">Teraz uderz! Kolejny atak zada +35% obrażeń.</b>':TACTICS[c.id].tip}${e.boss&&c.hp<e.hp*.35?'<b class="danger">SZAŁ: obrażenia bossa +20%</b>':''}</div><div class="battle-controls"><div class="combat-row"><button class="combat-button attack" data-action="fight:attack">${icon('sword')} Atak</button><button class="combat-button" data-action="fight:guard">${icon('shield')} Obrona</button><button class="combat-button" data-action="fight:potion:potion" ${!E.count(state,'potion')||(state.hp>=a.maxHp&&!c.ailment)?'disabled':''}>Mikstura <small>${E.count(state,'potion')} szt. · +45 życia</small></button></div><div class="combat-skills">${cls.skills.map(([id,name,cost])=>`<button class="combat-skill" data-action="fight:${id}" ${!state.skills[id]||c.cooldowns[id]>0||state.mana<cost?'disabled':''}><b>${name}</b><small>${!state.skills[id]?'Naucz się po awansie':c.cooldowns[id]>0?`Odnowienie: ${c.cooldowns[id]} tur`:`${cost} many · poz. ${state.skills[id]}`}</small></button>`).join('')}</div><div class="item-actions"><button class="inline-link" data-action="fight:potion:mana" ${!E.count(state,'mana')||state.mana>=a.maxMana?'disabled':''}>Mikstura many (${E.count(state,'mana')})</button>${E.count(state,'strongPotion')?'<button class="inline-link" data-action="fight:potion:strongPotion">Esencja życia (+100)</button>':''}<button class="inline-link" style="margin-left:auto" data-action="fight:flee">Wycofaj się</button></div></div><div class="battle-log" id="battle-log" aria-live="polite">${c.log.slice(-3).map(t=>`<p>${esc(t)}</p>`).join('')}</div></section>`;}
function showReward(){
 const p=state.pending;if(!p)return;modal='reward';$('#overlay').hidden=false;document.body.style.overflow='hidden';
 $('#overlay').innerHTML=`<section class="modal battle-modal" role="dialog" aria-modal="true" aria-label="Wynik walki"><div class="reward-body"><span class="reward-mark">${p.kind==='victory'?(p.elite?'ELITA POKONANA':'SZLAK ZNÓW JEST BEZPIECZNY'):'NIE KAŻDA WYPRAWA KOŃCZY SIĘ ZWYCIĘSTWEM'}</span><h2>${p.kind==='victory'?'Zwycięstwo!':'Strażnicy Cię odnaleźli.'}</h2><p>${p.kind==='victory'?'Pokonano: '+esc(p.enemy)+(p.turns?' · '+p.turns+' tur':''):'Wracasz do osady. Zachowujesz wyposażenie i postęp zadań.'}</p>${p.kind==='victory'?`<div class="reward-values"><b>+${p.gold} złota</b><b>+${p.xp} PD</b></div>${p.levels?`<div class="levelup">POZIOM ${state.level}! +${p.levels} pkt umiejętności · siły odnowione</div>`:''}${p.discovery?`<div class="loot-discovery">${esc(p.discovery)}</div>`:''}<div class="reward-loot">${p.loot.map((i,index)=>{const d=E.itemInfo(i);return `<article class="loot-card ${d.rarity} ${i.affix?'affix-loot':''}">${spr(d.sprite)}<b>${d.name}</b><small>${RARITY[d.rarity]}</small><div class="item-statline">${itemStats(d,i)}</div>${d.slot?comparisonHTML(d,i):''}${d.slot?button((d.level||1)>state.level?'Od poziomu '+d.level:'Zabierz i załóż','lootEquip:'+index,'secondary',(d.level||1)>state.level):''}</article>`}).join('')||'<p class="choice-note">Tym razem bez przedmiotów. Złoto i doświadczenie są już Twoje.</p>'}</div>${p.elite?`<p class="choice-note">Wyposażenie z bonusem: gwarancja najpóźniej za ${4-state.lootDry} kolejne zwycięstwa nad elitą.</p>`:''}`:''}<div class="reward-actions">${button(p.kind==='victory'?'Zabierz wszystkie łupy':'Wróć do osady','loot')}${p.kind==='victory'&&p.loot.length?button('Zostaw przedmioty','lootDiscard','ghost'):''}</div>${p.levels?'<p class="choice-note">Nowe zdolności znajdziesz w zakładce Bohater.</p>':''}</div></section>`;
}
function paintBattleBars(selector,metrics){
 const fills=$$(selector+' .meter i'),labels=$$(selector+' .meter-label span:last-child');
 if(fills.length!==metrics.length){const box=$(selector);if(box)box.innerHTML=metrics.map(([value,max,kind,label])=>meter(value,max,kind,label)).join('');return;}
 metrics.forEach(([value,max],i)=>{fills[i].style.width=Math.max(0,Math.min(100,value/max*100))+'%';labels[i].textContent=Math.floor(value)+' / '+max;});
}
function fight(action){
 if(busy)return;busy=true;const result=E.performAction(state,action);if(result.error){busy=false;return toast(result.error,true)}save();
 if(result.fled){busy=false;modal=null;$('#overlay').hidden=true;document.body.style.overflow='';render();return toast(result.note)}
 $$('[data-action^="fight:"]').forEach(b=>b.disabled=true);
 const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches,frames=result.frames||[],step=reduced?80:560;
 for(const [index,f] of frames.entries())setTimeout(()=>{
  const hero=$('#player-actor'),enemy=$('#enemy-actor');hero?.classList.remove('strike','hurt','guarded');enemy?.classList.remove('strike','hurt');
  paintBattleBars('#battle-player-bars',[[f.playerHp,f.maxHp,'hp','ŻYCIE'],[f.playerMana,f.maxMana,'mana','MANA']]);
  paintBattleBars('#battle-enemy-bars',[[f.enemyHp,f.enemyMax,'hp','ŻYCIE']]);
  if($('#battle-log'))$('#battle-log').innerHTML=`<p class="turn-caption">${esc(f.label)}</p>`;
  if(f.amount){const target=f.phase==='player'||f.phase==='dot'?enemy:hero;target?.classList.add('hurt');target?.insertAdjacentHTML('beforeend',`<b class="damage-float ${result.crit&&f.phase==='player'?'crit':''}">−${f.amount}${result.crit&&f.phase==='player'?'<small>KRYTYK</small>':''}</b>`);sound('hit');}
  if(f.phase==='player'){if(result.damage)hero?.classList.add('strike');else if(action==='guard')hero?.classList.add('guarded');if(result.heal)hero?.insertAdjacentHTML('beforeend',`<b class="damage-float healing">+${result.heal}</b>`);}
  if(f.phase==='enemy'&&f.amount)enemy?.classList.add('strike');
 },index*step);
 setTimeout(()=>{busy=false;refresh();showEncounter();if(result.won)sound('win');},frames.length*step+(reduced?0:240));
}
function huntSidebar(){
 const h=HUNTS.find(h=>h.id===state.trackedHunt&&!state.hunts.includes(h.id));
 if(!h)return `<section class="hunt-side"><span class="eyebrow">CEL KOLEJNEJ WYPRAWY</span><h3>Wybierz swoje polowanie</h3><p>Elity i materiały prowadzą do konkretnych nagród.</p>${button('Zobacz zlecenia','journal:hunts','secondary full')}</section>`;
 return `<section class="hunt-side"><span class="eyebrow">ŚLEDZONE ZLECENIE · POZ. ${h.level}</span><h3>${h.title}</h3><div class="quest-objectives">${E.huntProgress(state,h.id).map(g=>`<div class="objective ${g.value>=g.need?'done':''}"><i class="checkbox"></i><span>${g.label}</span><b>${Math.min(g.value,g.need)}/${g.need}</b></div>`).join('')}</div>${button(E.huntReady(state,h.id)?'Odbierz nagrodę':'Szczegóły polowania',E.huntReady(state,h.id)?'huntClaim:'+h.id:'journal:hunts','secondary full')}</section>`;
}
function questsHTML(){return `<nav class="journal-tabs" aria-label="Dziennik"><button data-action="journal:story" class="${journalTab==='story'?'active':''}">Fabuła</button><button data-action="journal:hunts" class="${journalTab==='hunts'?'active':''}">Polowania</button><button data-action="journal:bestiary" class="${journalTab==='bestiary'?'active':''}">Bestiariusz</button></nav>${journalTab==='hunts'?huntsHTML():journalTab==='bestiary'?bestiaryHTML():storyHTML()}`;}
function huntsHTML(){return `<div class="view-heading"><div class="eyebrow">ZBIERAJ · POLUJ · ODBIERAJ</div><h1>Szlak łowców</h1><p>Każde zlecenie ma określoną nagrodę. Wybierz cel i zobacz swój postęp.</p></div><div class="hunt-grid">${HUNTS.map(h=>{const reward=E.huntReward(state,h),d=E.itemInfo(reward),done=state.hunts.includes(h.id),ready=E.huntReady(state,h.id);return `<article class="hunt-card ${done?'completed':''}"><div class="hunt-heading"><span class="eyebrow">${h.giver} · POZ. ${h.level}</span><span class="badge ${ready?'gold':''}">${done?'UKOŃCZONE':ready?'GOTOWE':'ZLECENIE'}</span></div><h2>${h.title}</h2><p>${h.text}</p><div class="quest-objectives">${E.huntProgress(state,h.id).map(g=>`<div class="objective ${done||g.value>=g.need?'done':''}"><i class="checkbox"></i><span>${g.label}</span><b>${done?g.need:Math.min(g.value,g.need)}/${g.need}</b></div>`).join('')}</div><div class="hunt-reward ${d.rarity}">${spr(d.sprite)}<div><b>${d.name}</b><div class="item-statline">${itemStats(d,reward)}</div><small>Do założenia od poziomu ${d.level} · +${h.gold} zł · +${h.xp} PD</small></div></div>${done?'':`<div class="item-actions">${ready?button('Odbierz nagrodę','huntClaim:'+h.id):button(state.trackedHunt===h.id?'Śledzone':'Śledź cel','huntTrack:'+h.id,'secondary',state.trackedHunt===h.id)}${button('Pokaż na mapie','huntGo:'+h.id,'ghost')}</div>`}</article>`}).join('')}</div><p class="choice-note">Zwycięstwa nad elitami liczą się na bieżąco. Składniki oddajesz dopiero przy odbiorze nagrody. Zlecenia imienne wykonasz raz; kontrakt Straży za 5 zwycięstw pozostaje powtarzalny.</p>`;}
function bestiaryHTML(){return `<div class="view-heading"><div class="eyebrow">POZNAJ CEL SWOJEJ WYPRAWY</div><h1>Bestiariusz pogranicza</h1><p>Sprawdź łupy i taktykę. Elity pojawiają się w tych samych miejscach co ich zwykłe odmiany.</p></div><div class="loot-rule"><b>Wyposażenie z bonusem</b><p>Zwykły przeciwnik: dodatkowa szansa 12%. Elita: 35%, z gwarancją najpóźniej w czwartym kolejnym zwycięstwie bez tego łupu. Nagroda zawsze pasuje do klasy.</p><span class="badge gold">Gwarancja za maks. ${4-state.lootDry} elit</span></div><div class="bestiary-grid">${Object.entries(ENEMIES).map(([id,e])=>`<article class="bestiary-card"><header>${spr(e.sprite)}<div><span class="eyebrow">${e.region}</span><h2>${e.name}</h2><small>POZ. ${e.level} · ${e.hp} życia · ${state.kills[id]||0} zwycięstw</small></div></header><p>${TACTICS[id].tip}</p><div class="drop-list">${e.loot.map(([item,chance])=>`<div>${spr(ITEMS[item].sprite,'small')}<span>${ITEMS[item].name}</span><b>${Math.round(chance*100)}%</b></div>`).join('')}</div><div class="elite-note"><b>${ELITE_NAMES[id]}</b><small>Elita · poz. ${e.level+3} · ${state.eliteKills[id]||0} zwycięstw</small><p>${E.eliteRequirement(state,id)||'Polowanie odblokowane. Wybierz przycisk Elita pod mapą.'}</p></div>${button('Pokaż na mapie','enemyGo:'+id,'secondary full')}</article>`).join('')}</div>`;}
function enchantHTML(){const weapon=state.inventory.find(i=>i.uid===state.equipped.weapon),unlocked=state.quest>=3&&state.level>=5,affordable=E.count(state,'crystal')>=3&&E.count(state,'fang')>=4&&state.gold>=60;return `<section class="enchant-panel"><span class="eyebrow">WŁASNY KIERUNEK ROZWOJU</span><h3>Nasycenie broni</h3><p>${unlocked?'Wybierz dokładny bonus do założonej broni. Zastąpi jej obecny bonus; ulepszenie +1–3 zostaje.':'Toren odkryje tę sztukę po ukończeniu fabuły. Wymagany poziom 5.'}</p><div class="enchant-cost">Koszt: 3 odłamki, 4 kły i 60 złota.<br>Masz: ${E.count(state,'crystal')} odłamków · ${E.count(state,'fang')} kłów · ${state.gold} złota.</div><div class="affix-options">${Object.entries(AFFIXES).map(([id,a])=>`<button class="affix-option ${weapon?.affix===id?'active':''}" data-action="enchant:${id}" ${!unlocked||!affordable||!weapon||weapon.affix===id?'disabled':''}><b>${a.name}</b><small>${a.desc}${weapon?.affix===id?' · obecny':''}</small></button>`).join('')}</div></section>`;}
function claimHunt(id){const h=HUNTS.find(h=>h.id===id),r=E.claimHunt(state,id);if(r.error)return toast(r.error,true);save();render();sound('win');modal='hunt-reward';const d=E.itemInfo(r.reward);inventorySelected=state.inventory.at(-1).uid;openModal('Nagroda za wytrwałość',`<div class="reward-body"><span class="reward-mark">ZLECENIE UKOŃCZONE</span><h2>${h.title}</h2><div class="reward-values"><b>+${r.gold} złota</b><b>+${r.xp} PD</b></div><div class="reward-loot"><article class="loot-card affix-loot ${d.rarity}">${spr(d.sprite)}<b>${d.name}</b><div class="item-statline">${itemStats(d,r.reward)}</div></article></div>${r.levels?`<div class="levelup">Poziom ${state.level}! +${r.levels} pkt umiejętności.</div>`:''}${button('Zobacz wyposażenie','closeHero')}</div>`,'STRAŻ DZIĘKUJE');}
function questClaim(){const result=E.claimQuest(state);if(result.error)return toast(result.error,true);sound('win');refresh();if(view!=='world')render();if(modal&&!state.pending){closeModal();}modal='quest-reward';openModal('Opowieść toczy się dalej',`<div class="reward-body"><span class="reward-mark">ZADANIE UKOŃCZONE</span><h2>${QUESTS[state.quest-1].title}</h2><div class="reward-values"><b>+${result.gold} złota</b><b>+${result.xp} PD</b></div>${result.reward?`<div class="reward-loot"><div class="loot-card ${ITEMS[result.reward].rarity}">${spr(ITEMS[result.reward].sprite)}<b>${ITEMS[result.reward].name}</b><small>Nowa broń w plecaku</small></div></div>`:''}${result.levels?`<div class="levelup">Poziom ${state.level} · +${result.levels} pkt umiejętności</div>`:''}<p class="choice-note">${QUESTS[state.quest]?`Następny trop: ${QUESTS[state.quest].title}.`:'Nessa rozpoznaje odzyskany znak. Pogranicze ma nowego strażnika.'}</p>${button(result.reward?'Zobacz wyposażenie':'Dalej',result.reward?'closeHero':'close')}</div>`,'NAGRODA');}
function setupDrag(){$$('[draggable="true"]').forEach(b=>b.ondragstart=e=>{e.dataTransfer.setData('text/plain',b.dataset.uid)});$$('[data-slot]').forEach(b=>{b.ondragover=e=>{e.preventDefault();b.classList.add('drag-over')};b.ondragleave=()=>b.classList.remove('drag-over');b.ondrop=e=>{e.preventDefault();b.classList.remove('drag-over');const error=E.equip(state,e.dataTransfer.getData('text/plain'),b.dataset.slot);if(error)return toast(error,true);save();render();toast('Wyposażenie założone.')}});}
function transact(error,success,reopen=true){if(error)return toast(error,true);sound('coin');refresh();toast(success);if(reopen&&modal?.startsWith('service:'))openService(modal.split(':')[1],true);else if(view==='hero')render();}
function toggleGPS(){if(gpsWatch!==null){navigator.geolocation?.clearWatch(gpsWatch);gpsWatch=null;lastFix=null;gpsMessage='Spacer zatrzymany. Zebrany dystans pozostaje zapisany.';refresh();if(modal==='settings')openSettings();return;}if(!navigator.geolocation){toast('Ta przeglądarka nie udostępnia GPS.',true);return;}gpsMessage='Oczekiwanie na zgodę i dokładną pozycję…';refresh();gpsWatch=navigator.geolocation.watchPosition(p=>{const now=Date.now(),f={lat:p.coords.latitude,lon:p.coords.longitude,time:p.timestamp,accuracy:p.coords.accuracy};if(f.accuracy>60||now-f.time>30000){gpsMessage='Słaby sygnał GPS. Dystans naliczymy przy dokładności do 60 m.';refresh();return;}if(lastFix){const seconds=(f.time-lastFix.time)/1000,d=distance(lastFix,f);if(seconds>0&&seconds<120&&d>=12&&d<300&&d/seconds<4.5){if(E.recordGps(state,d)){toast('Zapasy ze spaceru: +3 zioła i +12 złota.');sound('coin')}lastFix=f;}else if(seconds>=120||d/Math.max(1,seconds)>=4.5)lastFix=f;}else lastFix=f;gpsMessage=`Spacer: ${Math.floor(state.gps.distance)} m · ${250-Math.floor(state.gps.distance)%250} m do zapasów`;refresh();},error=>{if(gpsWatch!==null)navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null;lastFix=null;gpsMessage=error.code===1?'GPS bez zgody. Nadal możesz swobodnie grać z domu.':'Nie udało się odczytać GPS. Spróbuj ponownie w otwartej przestrzeni.';refresh();toast(gpsMessage,true);},{enableHighAccuracy:true,maximumAge:0,timeout:20000});if(modal==='settings')openSettings();}
function distance(a,b){const r=Math.PI/180,lat=(b.lat-a.lat)*r,lon=(b.lon-a.lon)*r,x=Math.sin(lat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(lon/2)**2;return 6371000*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
async function importSave(file){if(!file)return;try{if(file.size>200000)throw Error('Plik jest zbyt duży.');const input=JSON.parse(await file.text());if(input.version!==1||!CLASSES[input.classId]||!Array.isArray(input.inventory))throw Error('To nie jest zapis wersji pixel art.');if(!confirm('Zaimportować zapis klasy '+CLASSES[input.classId].name+' i zastąpić jej postęp na tym urządzeniu?'))return;stopMovement();state=E.normalize(input);active=state.classId;save();$('#overlay').hidden=true;document.body.style.overflow='';modal=null;render();showEncounter();toast('Postać została zaimportowana.');}catch(error){toast(error.message||'Nieprawidłowy plik zapisu.',true)}}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,[type,...parts]=action.split(':'),value=parts.join(':');sound();
 if(type==='nav'){if(state.combat||state.pending)return showEncounter();stopMovement();view=value;closeModal();render();return;}
 if(type==='journal'){if(state.combat||state.pending)return showEncounter();if(!['story','hunts','bestiary'].includes(value))return;stopMovement();closeModal();journalTab=value;view='quest';render();return;}
 if(type==='huntTrack'){if(!HUNTS.some(h=>h.id===value))return;state.trackedHunt=value;save();render();return toast('Cel przypięty w dzienniku wyprawy.');}
 if(type==='huntClaim')return claimHunt(value);
 if(type==='enchant')return transact(E.enchant(state,value),'Bonus broni zmieniony: '+AFFIXES[value]?.desc+'.');
 if(type==='huntGo'||type==='enemyGo'){if(state.combat||state.pending)return showEncounter();const id=type==='enemyGo'?value:HUNTS.find(h=>h.id===value)?.target;if(!ENEMIES[id])return;closeModal();view='world';region=ENEMIES[id].x>80?'ruins':'forest';render();travel(id);$('#location-card')?.scrollIntoView?.({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'nearest'});return;}
 if(type==='elite'){if(travelTimer)return;return performLocation(value,true);}
 if(type==='location')return travel(value);
 if(type==='region'){region=value;$$('.region-tab').forEach(b=>b.classList.toggle('active',b.dataset.action==='region:'+value));setupMap();return;}
 if(type==='zoom'){zoom=value==='reset'?1:Math.min(1.65,Math.max(1,zoom+(value==='+'?.15:-.15)));setupMap();if(value==='reset')followWalker();return;}
 if(type==='interact'){if(travelTimer)return;return performLocation(value);}
 if(type==='service')return openService(value);
 if(type==='fight')return fight(value);
 if(type==='close')return closeModal();
 if(type==='help')return openHelp();
 if(type==='classes')return openClasses();
 if(type==='settings')return openSettings();
 if(type==='class'){if(!CLASSES[value])return;stopMovement();save();active=value;try{state=E.normalize(JSON.parse(localStorage.getItem(KEY+'.'+active))||E.createHero(active));}catch{state=E.createHero(active)}if(state.classId!==active)state=E.createHero(active);view='world';selected='inn';save();modal=null;$('#overlay').hidden=true;document.body.style.overflow='';render();showEncounter();return toast('Wybrano klasę: '+CLASSES[active].name);}
 if(type==='item'){inventorySelected=value;if($('#item-inspector'))$('#item-inspector').innerHTML=inventoryDetails(value);$$('.inventory-cell').forEach(b=>b.classList.toggle('selected',b.dataset.uid===value));return;}
 if(type==='gear'){inventorySelected=state.equipped[value]||null;if($('#item-inspector'))$('#item-inspector').innerHTML=inventorySelected?inventoryDetails(inventorySelected):'<div class="empty-note">Przeciągnij tutaj odpowiedni przedmiot.</div>';return;}
 if(type==='equip')return transact(E.equip(state,value),'Przedmiot założony.',false);
 if(type==='use'){const i=state.inventory.find(i=>i.uid===value);if(i)transact(E.usePotion(state,i.id),'Mikstura użyta.',false);return;}
 if(type==='sellOne')return transact(E.sell(state,value,1),'Przedmiot sprzedany.',false);
 if(type==='shopTab'){shopMode=value;shopSelected=null;return openService(modal.split(':')[1],true);}
 if(type==='shopSelect'){shopSelected=value;return openService(modal.split(':')[1],true);}
 if(type==='buySelected'){const qty=Number($('#shopQty')?.value);return transact(E.buy(state,shopSelected,qty,modal.split(':')[1]),'Zakup trafił do plecaka.');}
 if(type==='sellSelected'){const qty=Number($('#shopQty')?.value);return transact(E.sell(state,shopSelected,qty),'Przedmioty sprzedane.');}
 if(type==='upgrade')return transact(E.upgrade(state),'Broń wzmocniona. +2 do ataku.');
 if(type==='brew')return transact(E.brew(state),'Uwarzono miksturę życia.');
 if(type==='rest')return transact(E.rest(state),'Siły odnowione. Szlak czeka.');
 if(type==='bounty')return transact(E.claimBounty(state),'Kontrakt ukończony: +22 złota i +5 reputacji.');
 if(type==='learn')return transact(E.learn(state,value),'Umiejętność rozwinięta.',false);
 if(type==='questClaim')return questClaim();
 if(type==='closeHero'||type==='closeQuest'){closeModal();if(type==='closeQuest')journalTab='story';view=type==='closeHero'?'hero':'quest';render();return;}
 if(type==='loot'||type==='lootDiscard'||type==='lootEquip'){const result=E.claimLoot(state,type==='lootDiscard',type==='lootEquip'?Number(value):null);if(result)return toast(result,true);modal=null;$('#overlay').hidden=true;document.body.style.overflow='';save();render();sound('coin');return;}
 if(type==='gps')return toggleGPS();
 if(type==='sound'){state.sound=!state.sound;save();sound('win');openSettings();return;}
 if(type==='rename'){state.name=$('#heroName').value.trim().slice(0,18)||'Wędrowiec';refresh();toast('Imię zapisane.');return;}
 if(type==='export'){save();const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='Time4Heroes-pixel-'+state.classId+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(type==='import')return $('#importFile').click();
});
document.addEventListener('change',e=>{if(e.target.id==='importFile')importSave(e.target.files[0]);});
document.addEventListener('keydown',e=>{const direction=N.keyDirection(e.key);if(direction&&movementAllowed()&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.target?.closest?.('input,textarea,select,[contenteditable="true"]')){e.preventDefault();motion.keys.add(direction);motion.route=[];motion.arrival=null;travelTimer=null;updateLocationCard();wakeMovement();return;}if(e.key==='Escape'){stopMovement();closeModal();}if(e.key==='Tab'&&!$('#overlay').hidden){const nodes=$$('#overlay button:not(:disabled),#overlay input,#overlay a');if(nodes.length){const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}}});
document.addEventListener('keyup',e=>{const direction=N.keyDirection(e.key);if(direction)motion.keys.delete(direction);});
window.addEventListener('blur',()=>stopMovement());
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeModal();});
window.addEventListener('resize',()=>{if(view==='world')setupMap()});
window.addEventListener('pagehide',()=>stopMovement());
document.addEventListener('visibilitychange',()=>{if(!document.hidden){E.applyOffline(state);refresh();}else stopMovement();});
setInterval(()=>{E.applyOffline(state);if(!state.combat&&!state.pending)refresh();},30000);
render();save();showEncounter();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
